item.content:encoded:
{"styles":{"typography":{"fontFamily":"var(--wp--preset--font-family--domine)","fontSize":"var(--wp--preset--font-size--large)"},"css":".no-underline a {
	text-decoration: none;
}

.animated-separator {
	height: 2px;
/* Separator thickness */
	width: 70%;
/* Separator width */
	margin: 40px auto;
/* Centers the separator and adds space above/below */
	background: linear-gradient(270deg, #d4af37, #f7e8aa, #d4af37);
/* Gold gradient colors */
	background-size: 200% 200%;
	animation: moveGradient 3s ease infinite;
}

@keyframes moveGradient {
	0% {
		background-position: 100% 50%;
	}

	50% {
		background-position: 0 50%;
	}

	100% {
		background-position: 100% 50%;
	}
}"},"version":3,"isGlobalStylesUserThemeJSON":true}
